// OFFLINE DEMONSTRATION DATA: entirely synthetic, not the event spreadsheet.
const DATA = {"parts":[{"part_id":"DEMO-P001","description":"Illustrative component","category":"Demo","unit_cost_aed":100,"preferred_supplier":"DEMO-S01","qualified_alternates":null,"lead_time_days":10,"min_order_qty":10,"alternate_price_premium_pct":null}],"products":[{"product_id":"DEMO-FG01","description":"Illustrative finished good","selling_price_aed":1000}],"bom":[{"product_id":"DEMO-FG01","part_id":"DEMO-P001","qty_per_unit":2}],"inventory":[{"part_id":"DEMO-P001","warehouse":"Demo warehouse","qty_on_hand":20}],"plan":[{"order_id":"DEMO-MO01","product_id":"DEMO-FG01","qty":20,"start_date":"2026-11-01","due_date":"2026-11-15","customer":"Fictional customer","revenue_aed":20000}],"pos":[{"po_id":"DEMO-PO01","part_id":"DEMO-P001","supplier_id":"DEMO-S01","qty":40,"ship_date":"2026-11-01","eta_jebel_ali":"2026-11-10","status":"in transit","mode":"sea"}]};
const pid = i => String($input.all()[i].json.part_id).trim().toUpperCase();
const parts = Object.fromEntries(DATA.parts.map(p => [p.part_id, p]));
const prod = Object.fromEntries(DATA.products.map(p => [p.product_id, p]));
return $input.all().map((it, i) => {
  const part_id = pid(i);
  const p = parts[part_id];
  if (!p) { const e = { detail: 'unknown part' }; return { json: { part_id, inventory: e, shipments: e, bom: e, plan: e } }; }
  const bom = DATA.bom.filter(b => b.part_id === part_id);          // get_bom(part_id): BOM rows merged with the product
  const bomOut = bom.map(b => ({ ...b, description: prod[b.product_id]?.description, selling_price_aed: prod[b.product_id]?.selling_price_aed }));
  const qpu = Object.fromEntries(bom.map(b => [b.product_id, b.qty_per_unit]));
  const plan = DATA.plan.filter(m => qpu[m.product_id] !== undefined).map(m => ({ ...m, qty_per_unit: qpu[m.product_id] }));
  return { json: { part_id, scenario_clock: $('Config').first().json._cfg.offline_now,
    inventory: { part: p, stock: DATA.inventory.filter(r => r.part_id === part_id) },
    shipments: DATA.pos.filter(r => r.part_id === part_id),
    bom: bomOut, plan } };
});

// ===== SETTINGS. With OFFLINE_MODE = true you can just press Execute: no bridge, tunnel or key needed. =====
const OFFLINE_MODE = false;  // true  = use the built-in copy of the P4 workbook (practice scenario start date)
                             // false = call the live FastAPI bridge below
const OFFLINE_NOW  = '2026-09-03T00:00:00';                                         // simulated "today" used offline (practice_01)
const BRIDGE_URL   = 'http://127.0.0.1:8000'; // live mode only: current tunnel address
const P4_API_KEY   = 'REPLACE_WITH_BRIDGE_API_KEY';                                          // live mode only: key the bridge was started with
const GROQ_API_KEY = '';                                                             // optional: only for the written explanation
// ===================================================================================================

if (!OFFLINE_MODE && !P4_API_KEY.trim()) throw new Error('Config: P4_API_KEY is empty (live mode).');
const base = BRIDGE_URL.trim().replace(/\/+$/, '').replace(/\/call$/, '');
const cfg = { offline: OFFLINE_MODE === true, offline_now: OFFLINE_NOW, bridge_url: base, api_key: P4_API_KEY.trim(), groq_api_key: GROQ_API_KEY.trim() };

// pass the incoming items through untouched; the settings ride along in _cfg
return $input.all().map(i => ({ json: { ...i.json, _cfg: cfg } }));

// Build Agent 4 handoffs from every incident assessed by Agent 3.
// Agent 3 assesses impact; Agent 2 owns disruption recording.

const impacts = $('Assess Impact').all().map(i => i.json);
const explanations = $('Write explaination openAI').all().map(i => i.json);

if (!impacts.length) {
  throw new Error('No Assess Impact results were found.');
}

function getExplanation(item) {
  if (!item) return '';

  let value = item;

  // Handle common HTTP Request response wrappers.
  for (let i = 0; i < 3; i++) {
    if (typeof value === 'string') {
      try {
        value = JSON.parse(value);
        continue;
      } catch {
        break;
      }
    }

    if (value && typeof value === 'object' && value.body !== undefined) {
      value = value.body;
      continue;
    }

    if (value && typeof value === 'object' && value.data !== undefined && !value.choices) {
      value = value.data;
      continue;
    }

    break;
  }

  const content =
    value?.choices?.[0]?.message?.content ??
    value?.output ??
    '';

  return String(content).replace(/\s+/g, ' ').trim().slice(0, 900);
}

const results = [];

for (let i = 0; i < impacts.length; i++) {
  const a = impacts[i];
  const llm = getExplanation(explanations[i]);
  const explanation = llm || a.assessment || null;
  const parts = Array.isArray(a.parts) ? a.parts : [];

  const common = {
    agent: 'agent3_impact_analyst',
    incident_id: a.incident_id ?? null,
    scenario_id: a.scenario_id ?? null,
    supplier_id: a.supplier_id ?? null,
    delay_days: a.delay_days ?? null,
    disruption_type: a.disruption_type ?? 'delay',
    source_ids: a.source_ids ?? [],
    overall_risk_level: a.overall_risk_level ?? null,
    requires_human_review: a.requires_human_review === true,
    warnings: a.warnings ?? [],
    explanation,
    assessment: a.assessment ?? null
  };

  // Only pass genuine production shortages to Agent 4.
  const risky = parts.filter(p =>
    p.status === 'ok' &&
    p.production_at_risk === true &&
    Number(p.shortage_quantity) > 0
  );

  if (!risky.length) {
    results.push({
      json: {
        ...common,
        status: a.requires_human_review
          ? 'needs_human_review'
          : 'no_action_needed',
        production_at_risk: false,
        parts: parts.map(p => ({
          part_id: p.part_id ?? null,
          status: p.status ?? null,
          risk_level: p.risk_level ?? null,
          production_at_risk: p.production_at_risk ?? false,
          error: p.error ?? null
        }))
      }
    });

    continue;
  }

  for (const p of risky) {
    const orders = Array.isArray(p.affected_orders)
      ? p.affected_orders
      : [];

    results.push({
      json: {
        ...common,
        status: 'shortage_handoff_to_agent4',
        part_id: p.part_id,
        production_at_risk: true,
        risk_level: p.risk_level ?? null,
        available_stock: p.available_stock ?? null,
        required_quantity: p.required_quantity ?? null,
        shortage_quantity: p.shortage_quantity,
        baseline_shortage_quantity: p.baseline_shortage_quantity ?? null,
        incoming_before_shortage: p.incoming_before_peak_deficit ?? null,
        required_by: p.required_by ?? null,
        need_date: p.required_by ?? null,
        days_until_shortage: p.days_until_shortage ?? null,
        affected_orders: orders,
        revenue_at_risk_aed: p.revenue_at_risk_aed ?? null,
        delayed_pos: p.delayed_pos ?? [],
        formula: p.formula ?? null,
        reasoning_summary: p.formula
          ? `${p.formula}. Orders at risk: ${orders.length ? orders.join(', ') : 'not specified'}.`
          : null
      }
    });
  }
}

return results;

// ===== ASSESS IMPACT =====
// Deterministic calculations. One output item per verified incident.
// Agent 3 assesses impact only; Agent 2 owns disruption verification.

const partItems = $('Build Part Items').all();

// Offline path: data comes from 'Offline Data'. Live path: from the four HTTP nodes.
let off = null;
try { off = $('Offline Data').all(); } catch (e) { off = null; }
const wrap = f => off.map(x => ({ json: { data: x.json[f] } }));
const inventoryItems = off ? wrap('inventory') : $('Get Inventory').all();
const shipmentItems  = off ? wrap('shipments')  : $('Get Shipments').all();
const bomItems       = off ? wrap('bom')        : $('Get BOM').all();
const planItems      = off ? wrap('plan')       : $('Get Production Plan').all();

const DAY = 86400000;

const s = v => String(v ?? '').trim();

function dayMs(value) {
  if (!value) return null;
  const ms = Date.parse(String(value).slice(0, 10) + 'T00:00:00Z');
  return Number.isFinite(ms) ? ms : null;
}

const iso = ms => new Date(ms).toISOString().slice(0, 10);

function readResponse(items, index, name) {
  const item = items[index];

  if (!item) {
    throw new Error(`${name}: no response for part item #${index}`);
  }

  let value = item.json.data ?? item.json.body ?? item.json;

  if (typeof value === 'string') {
    try {
      value = JSON.parse(value);
    } catch {
      throw new Error(`${name}: response is not valid JSON`);
    }
  }

  if (value?.detail || value?.error) {
    throw new Error(
      `${name} failed: ${JSON.stringify(value.detail ?? value.error)}`
    );
  }

  return value;
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

// Simulate stock movements in date order.
// Receipts are counted before demand on the same date.
function simulate(stock, receipts, demands) {
  const events = [
    ...receipts.map(r => ({ ...r, kind: 0 })),
    ...demands.map(d => ({ ...d, kind: 1 }))
  ].sort((a, b) =>
    a.day - b.day ||
    a.kind - b.kind ||
    String(a.order_id || a.po_id).localeCompare(
      String(b.order_id || b.po_id)
    )
  );

  let balance = stock;
  let minBalance = stock;
  let cumulativeDemand = 0;
  let cumulativeReceipts = 0;

  let peak = {
    cumDem: 0,
    cumRec: 0,
    day: null
  };

  let firstShort = null;
  const affected = [];

  for (const event of events) {
    if (event.kind === 0) {
      balance += event.qty;
      cumulativeReceipts += event.qty;
    } else {
      balance -= event.qty;
      cumulativeDemand += event.qty;

      if (balance < 0) {
        affected.push(event);

        if (firstShort === null) {
          firstShort = event.day;
        }
      }
    }

    if (balance < minBalance) {
      minBalance = balance;

      peak = {
        cumDem: cumulativeDemand,
        cumRec: cumulativeReceipts,
        day: event.day
      };
    }
  }

  return {
    shortage: Math.max(0, -minBalance),
    peak,
    firstShort,
    affected
  };
}

const RECEIPT_LAG_DAYS = 0;
const results = [];

// ===== ASSESS EACH PART INDEPENDENTLY =====

for (let i = 0; i < partItems.length; i++) {
  const item = partItems[i].json;

  const ctx = {
    incident_id: s(item.incident_id) || 'unspecified',
    scenario_id: s(item.scenario_id) || null,
    supplier_id: s(item.supplier_id).toUpperCase(),
    delay_days: Number(item.delay_days) || 0,
    cancelled: item.cancelled === true,
    source_ids: asArray(item.source_ids),
    affected_po_ids: asArray(item.affected_po_ids)
      .map(x => s(x).toUpperCase()),
    include_in_transit: item.include_in_transit !== false
  };

  const part_id = s(item.part_id).toUpperCase();
  const todayMs = dayMs(item.today);

  const out = {
    part_id,
    incident_id: ctx.incident_id,
    status: 'ok',
    warnings: []
  };

  try {
    if (!todayMs) {
      throw new Error(
        item.time_error || 'Missing or invalid simulated date'
      );
    }

    const inv = readResponse(inventoryItems, i, 'Get Inventory');
    const pos = readResponse(shipmentItems, i, 'Get Shipments');
    const bom = readResponse(bomItems, i, 'Get BOM');
    const plan = readResponse(planItems, i, 'Get Production Plan');

    // ----- INVENTORY -----

    const stockRows = asArray(inv.stock);

    const stock = stockRows.reduce(
      (total, row) => total + Number(row.qty_on_hand || 0),
      0
    );

    const leadTime = Number(inv.part?.lead_time_days ?? 0);

    // ----- OPEN PURCHASE ORDERS / SHIPMENTS -----

    const shipmentRows = Array.isArray(pos)
      ? pos
      : asArray(pos.shipments);

    const terminalStatuses = new Set([
      'delivered',
      'received',
      'cancelled',
      'canceled',
      'closed',
      'completed'
    ]);

    const cancelStatuses = new Set(['cancelled', 'canceled']);

    const open = [];

    for (const p of shipmentRows) {
      const status = s(p.status).toLowerCase();

      // FIX (cancelled supplier): if this incident IS the cancellation of this PO,
      // the simulator may already show it as cancelled. Keep it so the baseline
      // still contains the receipt we have now lost.
      const cancelledByThisIncident =
        ctx.cancelled &&
        cancelStatuses.has(status) &&
        s(p.supplier_id).toUpperCase() === ctx.supplier_id &&
        ctx.affected_po_ids.includes(s(p.po_id).toUpperCase());

      if (terminalStatuses.has(status) && !cancelledByThisIncident) continue;

      const qty = Number(p.qty);
      const eta = dayMs(p.eta_jebel_ali ?? p.eta);

      if (!p.po_id || !Number.isFinite(qty) || qty <= 0 || eta === null) {
        out.warnings.push(
          'Ignored shipment with missing PO ID, quantity or valid ETA'
        );
        continue;
      }

      open.push({
        po_id: s(p.po_id).toUpperCase(),
        supplier_id: s(p.supplier_id).toUpperCase(),
        qty,
        status,
        eta
      });
    }

    const supplierPOs = open.filter(p =>
      p.supplier_id === ctx.supplier_id
    );

    const eligiblePOs = supplierPOs.filter(p =>
      ctx.cancelled ||
      ctx.include_in_transit ||
      p.status !== 'in transit'
    );

    let hit = [];
    let poReferenceUnmatched = false;
    let poScopeAssumed = false;

    if (ctx.affected_po_ids.length) {
      hit = eligiblePOs.filter(p =>
        ctx.affected_po_ids.includes(p.po_id)
      );

      const matchedIds = new Set(hit.map(p => p.po_id));

      const missingIds = ctx.affected_po_ids.filter(
        id => !matchedIds.has(id)
      );

      if (missingIds.length) {
        poReferenceUnmatched = true;

        out.warnings.push(
          `Affected PO IDs not matched to eligible open POs: ${missingIds.join(', ')}. Unmatched POs were NOT substituted with other POs.`
        );
      }
    } else {
      // Supplier-level disruption: all eligible open POs
      // from this supplier for this requested part are assessed.
      hit = eligiblePOs;

      if (hit.length) {
        poScopeAssumed = true;

        out.warnings.push(
          `No specific affected PO IDs supplied. Supplier-level scope applied to ${hit.length} eligible open PO(s); human review required.`
        );
      }
    }

    if (!hit.length) {
      out.warnings.push(
        `No matching open PO from ${ctx.supplier_id} will be ${ctx.cancelled ? 'cancelled' : 'delayed'} for ${part_id}.`
      );
    }

    const hitIds = new Set(hit.map(p => p.po_id));

    // Cancelled POs never arrive, so they are removed from the disrupted scenario.
    const recDisrupted = open
      .filter(p => !(ctx.cancelled && hitIds.has(p.po_id)))
      .map(p => ({
      po_id: p.po_id,
      qty: p.qty,
      day: Math.max(
        p.eta +
          (hitIds.has(p.po_id) ? ctx.delay_days * DAY : 0) +
          RECEIPT_LAG_DAYS * DAY,
        todayMs
      )
    }));

    const recBase = open.map(p => ({
      po_id: p.po_id,
      qty: p.qty,
      day: Math.max(
        p.eta + RECEIPT_LAG_DAYS * DAY,
        todayMs
      )
    }));

    // ----- BOM AND MANUFACTURING DEMAND -----

    const bomRows = asArray(bom);
    const planRows = asArray(plan);

    const perUnit = {};
    const price = {};

    for (const b of bomRows) {
      perUnit[b.product_id] = Number(b.qty_per_unit);
      price[b.product_id] = Number(b.selling_price_aed);
    }

    // FIX (overdue orders): an order whose due date has passed is NOT dropped.
    // It stays open demand until the plan says it is finished. Before this fix,
    // a late order vanished the day after its due date and HIGH turned into LOW.
    // OVERDUE_GRACE_DAYS only stops very old orders from counting forever.
    const OVERDUE_GRACE_DAYS = 30;

    const doneStatuses = new Set([
      'completed', 'complete', 'done', 'finished',
      'closed', 'shipped', 'delivered',
      'cancelled', 'canceled'
    ]);

    const overdueOrders = [];

    const mos = planRows.filter(m => {
      const due = dayMs(m.due_date);
      if (due === null) return false;
      if (doneStatuses.has(s(m.status).toLowerCase())) return false;
      if (due >= todayMs) return true;
      if (due < todayMs - OVERDUE_GRACE_DAYS * DAY) return false;
      overdueOrders.push(s(m.order_id));
      return true;
    });

    const demands = [];

    for (const m of mos) {
      const qtyPerUnit = Number(
        m.qty_per_unit ?? perUnit[m.product_id] ?? 0
      );

      const qty = Number(m.qty) * qtyPerUnit;
      const start = dayMs(m.start_date);

      if (!Number.isFinite(qty) || qty <= 0) continue;

      demands.push({
        order_id: s(m.order_id),
        product_id: s(m.product_id),
        qty,
        day: Math.max(start ?? todayMs, todayMs),
        revenue: Number(
          m.revenue_aed ??
          (Number(m.qty) * (price[m.product_id] || 0))
        )
      });
    }

    if (!demands.length) {
      out.no_demand = true;
      out.warnings.push(
        `No open manufacturing orders use ${part_id}`
      );
    }

    // ----- BASELINE VS DISRUPTED SCENARIO -----

    const disrupted = simulate(stock, recDisrupted, demands);
    const baseline = simulate(stock, recBase, demands);

    const baselineIds = new Set(
      baseline.affected.map(e => e.order_id)
    );

    const disruptedIds = new Set(
      disrupted.affected.map(e => e.order_id)
    );

    const newlyAffectedOrders = [
      ...disruptedIds
    ].filter(id => !baselineIds.has(id));

    const incrementalShortage = Math.max(
      0,
      disrupted.shortage - baseline.shortage
    );

    // Detect an earlier shortage even when maximum shortage
    // quantity does not increase.
    const shortageOccursEarlier =
      disrupted.firstShort !== null &&
      (
        baseline.firstShort === null ||
        disrupted.firstShort < baseline.firstShort
      );

    const demandByOrder = {};

    for (const d of demands) {
      demandByOrder[d.order_id] = d.revenue;
    }

    const newlyAffectedRevenue = {};

    for (const id of newlyAffectedOrders) {
      newlyAffectedRevenue[id] = demandByOrder[id] ?? 0;
    }

    const revenueAtRisk = Object.values(
      newlyAffectedRevenue
    ).reduce((a, v) => a + v, 0);

    const productionAtRisk =
      incrementalShortage > 0 ||
      newlyAffectedOrders.length > 0 ||
      shortageOccursEarlier;

    const impactDate =
      disrupted.firstShort === null
        ? null
        : disrupted.firstShort;

    const daysToImpact =
      impactDate === null
        ? null
        : Math.round((impactDate - todayMs) / DAY);

    const dailyUse = demands.length
      ? demands.reduce((a, d) => a + d.qty, 0) /
        Math.max(
          1,
          Math.round(
            (Math.max(...demands.map(d => d.day)) - todayMs) / DAY
          ) + 1
        )
      : 0;

    let risk = 'LOW';

    if (productionAtRisk) {
      risk = daysToImpact !== null && daysToImpact < leadTime
        ? 'HIGH'
        : 'MEDIUM';
    }

    const delayedPOs = hit.map(p => ({
      po_id: p.po_id,
      qty: p.qty,
      original_eta: iso(p.eta),
      cancelled: ctx.cancelled,
      new_eta: ctx.cancelled
        ? null
        : iso(Math.max(p.eta + ctx.delay_days * DAY, todayMs))
    }));

    // Tell the reader when a late order is part of the problem.
    const overdueShort = overdueOrders.filter(id => disruptedIds.has(id));

    if (overdueShort.length) {
      out.warnings.push(
        `Past due date and still short: ${overdueShort.join(', ')}. Counted as open demand until the plan shows it finished.`
      );
    }

    // ----- NEW: ACTUAL PRODUCTION REQUIRED DATE -----
    // Use the start_date of newly affected manufacturing orders.
    // Do not substitute shipment ETA or shortage date.

    const startDatesFor = ids => planRows
      .filter(m => ids.includes(s(m.order_id)))
      .map(m => dayMs(m.start_date))
      .filter(ms => ms !== null);

    let affectedStartDates = startDatesFor(newlyAffectedOrders);

    // FIX: a shortage can get bigger or earlier without hitting a NEW order.
    // Agent 4 needs a date in that case too, so fall back to the start date
    // of the orders that are short in the disrupted scenario.
    if (!affectedStartDates.length && productionAtRisk) {
      affectedStartDates = startDatesFor([...disruptedIds]);

      if (affectedStartDates.length) {
        out.warnings.push(
          'No newly affected order; required_by taken from orders already short in the disrupted scenario.'
        );
      }
    }

    const requiredBy = affectedStartDates.length
      ? iso(Math.min(...affectedStartDates))
      : null;

    Object.assign(out, {
      available_stock: stock,
      incoming_po_qty_total: open.reduce(
        (a, p) => a + p.qty,
        0
      ),
      incoming_before_peak_deficit: disrupted.peak.cumRec,
      required_quantity: disrupted.peak.cumDem,

      shortage_quantity: disrupted.shortage,
      baseline_shortage_quantity: baseline.shortage,
      shortage_caused_by_disruption: incrementalShortage,

      shortage_start_date:
        disrupted.firstShort === null
          ? null
          : iso(disrupted.firstShort),

      // NEW: passed to Agent 4
      required_by: requiredBy,

      baseline_shortage_start_date:
        baseline.firstShort === null
          ? null
          : iso(baseline.firstShort),

      shortage_occurs_earlier_due_to_disruption:
        shortageOccursEarlier,

      days_until_shortage: daysToImpact,
      inventory_days_cover: daysToImpact,

      avg_daily_consumption: Math.round(dailyUse * 10) / 10,
      replacement_lead_time_days: leadTime,

      production_at_risk: productionAtRisk,
      risk_level: risk,

      affected_orders: [...disruptedIds],
      newly_affected_orders: newlyAffectedOrders,
      overdue_orders_still_short: overdueShort,

      revenue_at_risk_aed: Math.round(revenueAtRisk),
      newly_affected_order_revenue: newlyAffectedRevenue,

      products_using_part: Object.keys(perUnit),
      delayed_pos: delayedPOs,

      po_reference_unmatched: poReferenceUnmatched,
      po_scope_assumed: poScopeAssumed,

      formula:
        `Disrupted shortage ${disrupted.shortage} - baseline shortage ${baseline.shortage} = disruption-caused shortage ${incrementalShortage}`
    });

  } catch (e) {
    Object.assign(out, {
      status: 'error',
      error: String(e.message || e),
      production_at_risk: null,
      risk_level: 'UNKNOWN',
      requires_human_review: true,
      affected_orders: [],
      newly_affected_orders: [],
      newly_affected_order_revenue: {},
      revenue_at_risk_aed: 0,
      shortage_quantity: 0,
      shortage_caused_by_disruption: 0
    });
  }

  results.push({
    ...out,
    scenario_id: ctx.scenario_id,
    supplier_id: ctx.supplier_id,
    delay_days: ctx.delay_days,
    disruption_type: ctx.cancelled ? 'cancellation' : 'delay',
    source_ids: ctx.source_ids,
    _group_key: JSON.stringify([
      ctx.incident_id,
      ctx.supplier_id,
      ctx.delay_days,
      ctx.cancelled,
      [...ctx.source_ids].sort()
    ])
  });
}

// ===== GROUP PART RESULTS BY INCIDENT =====

const groups = new Map();

for (const r of results) {
  if (!groups.has(r._group_key)) {
    groups.set(r._group_key, []);
  }

  groups.get(r._group_key).push(r);
}

const riskRank = {
  HIGH: 4,
  MEDIUM: 3,
  LOW: 2,
  UNKNOWN: 1
};

const output = [];

for (const groupResults of groups.values()) {
  const first = groupResults[0];

  const orderRevenue = {};

  for (const r of groupResults) {
    for (const [id, revenue] of Object.entries(
      r.newly_affected_order_revenue || {}
    )) {
      orderRevenue[id] = Math.max(
        orderRevenue[id] ?? 0,
        Number(revenue) || 0
      );
    }
  }

  const affectedOrders = Object.keys(orderRevenue);

  const overallRisk = groupResults.reduce(
    (best, r) =>
      (riskRank[r.risk_level] || 0) > (riskRank[best] || 0)
        ? r.risk_level
        : best,
    'LOW'
  );

  const partsAtRisk = groupResults.filter(
    r => r.production_at_risk === true
  );

  const errors = groupResults.filter(
    r => r.status === 'error'
  );

  const unmatchedPOs = groupResults
    .filter(r => r.po_reference_unmatched)
    .map(r => r.part_id);

  const assumedPOScope = groupResults
    .filter(r => r.po_scope_assumed)
    .map(r => r.part_id);

  const lines = groupResults.map(r => {
    if (r.status === 'error') {
      return `${r.part_id}: assessment failed (${r.error})`;
    }

    if (r.production_at_risk) {
      return (
        `${r.part_id}: stock ${r.available_stock}, ` +
        `disrupted shortage ${r.shortage_quantity}, ` +
        `baseline shortage ${r.baseline_shortage_quantity}, ` +
        `additional shortage ${r.shortage_caused_by_disruption}; ` +
        `newly affected orders ${r.newly_affected_orders.join(', ') || 'none'}; ` +
        `revenue at risk AED ${r.revenue_at_risk_aed}`
      );
    }

    return (
      `${r.part_id}: no additional production impact ` +
      `attributable to this disruption`
    );
  });

  const warnings = groupResults.flatMap(r =>
    (r.warnings || []).map(w => `${r.part_id}: ${w}`)
  );

  output.push({
    json: {
      incident_id: first.incident_id,
      scenario_id: first.scenario_id,
      supplier_id: first.supplier_id,
      delay_days: first.delay_days,
      disruption_type: first.disruption_type,
      source_ids: first.source_ids,

      overall_risk_level: errors.length
        ? 'UNKNOWN'
        : overallRisk,

      production_at_risk: partsAtRisk.length > 0,

      requires_human_review:
        errors.length > 0 ||
        unmatchedPOs.length > 0 ||
        assumedPOScope.length > 0,

      po_reference_unmatched: unmatchedPOs,
      po_scope_assumed: assumedPOScope,

      affected_orders: affectedOrders,

      revenue_at_risk_aed: Math.round(
        Object.values(orderRevenue).reduce((a, v) => a + v, 0)
      ),

      assessment:
        `Supplier ${first.supplier_id} disruption; ` +
        (first.disruption_type === 'cancellation'
          ? 'PO cancelled, will not arrive. '
          : `${first.delay_days}-day delay. `) +
        `Overall risk ${errors.length ? 'UNKNOWN' : overallRisk}. ` +
        lines.join(' | '),

      warnings,

      parts: groupResults.map(({ _group_key, ...r }) => r)
    }
  });
}

return output;

// Create one item per affected part, preserving incident details.
// Only process validated handoffs. Ignore no_action_needed and rejected handoffs.

const handoffs = $('Validate Handoff')
  .all()
  .map(item => item.json)
  .filter(v =>
    v &&
    v.ok === true &&
    v.ctx &&
    Array.isArray(v.ctx.part_ids) &&
    v.ctx.part_ids.length > 0
  );

const times = $input.all().map(item => item.json);

// No valid handoffs means there is nothing to assess.
if (!handoffs.length) {
  return [];
}

// If the clock call failed we do NOT crash the run. The part is passed on
// with today = null, and Assess Impact turns it into UNKNOWN + human review.

const results = [];

for (let i = 0; i < handoffs.length; i++) {
  const v = handoffs[i];
  let t = times[i] ?? times[0] ?? {};

  if (typeof t === 'string') {
    try { t = JSON.parse(t); } catch { t = {}; }
  }
  if (t && t.data && !t.now) {
    try { t = typeof t.data === 'string' ? JSON.parse(t.data) : t.data; } catch { t = {}; }
  }

  const timeOk = !!(t && !t.detail && !t.error && t.now);

  for (const part_id of v.ctx.part_ids) {
    results.push({
      json: {
        ...v.ctx,
        part_id,
        today: timeOk ? String(t.now).slice(0, 10) : null,
        time_error: timeOk
          ? null
          : 'get_current_time failed: ' + JSON.stringify(t?.detail ?? t?.error ?? t ?? null).slice(0, 200)
      }
    });
  }
}

return results;

const items = $input.all();

if (!items.length) {
  throw new Error('No input reached Result: rejected / skipped.');
}

return items.map(item => {
  const j = item.json ?? {};

  return {
    json: {
      ...j,
      ok: false,
      status: j.status === 'no_action_needed'
        ? 'no_action_needed'
        : (j.status || 'rejected_bad_input'),
      errors: Array.isArray(j.errors) ? j.errors : [],
      warnings: Array.isArray(j.warnings) ? j.warnings : [],
      ctx: null
    }
  };
});

const inputs = $input.all();
const results = [];

const s = v => String(v ?? '').trim();
const arr = v => Array.isArray(v) ? v : [];

function unwrap(raw) {
  let value = raw;

  for (let i = 0; i < 6; i++) {
    if (typeof value === 'string') {
      value = JSON.parse(value);
      continue;
    }

    if (value && typeof value === 'object' && !Array.isArray(value)) {
      let unwrapped = false;

      for (const key of ['handoff', 'output', 'body', 'data', 'result']) {
        if (value[key] !== undefined) {
          value = value[key];
          unwrapped = true;
          break;
        }
      }

      if (unwrapped) continue;
    }

    break;
  }

  return value;
}

for (const item of inputs) {
  let h;

  try {
    h = unwrap(item.json);
  } catch (e) {
    results.push({
      json: {
        ok: false,
        status: 'invalid_agent2_output',
        errors: ['Could not parse Agent 2 output'],
        warnings: [],
        ctx: null
      }
    });
    continue;
  }

  if (!h || typeof h !== 'object' || Array.isArray(h)) {
    results.push({
      json: {
        ok: false,
        status: 'invalid_agent2_output',
        errors: ['Invalid Agent 2 JSON object'],
        warnings: [],
        ctx: null
      }
    });
    continue;
  }

  const disruptions = arr(h.disruptions);
  const rejected = arr(h.rejected_disruptions);
  const suspicious = arr(h.suspicious_emails);
  const legitimate = arr(h.verified_legitimate_emails);

  // CASE 1: No verified disruption.
  if (h.has_verified_disruption !== true) {
    const invalidClaims = disruptions.length > 0;
    const needsReview =
      h.requires_human_review === true ||
      h.status === 'needs_human_review' ||
      invalidClaims;

    results.push({
      json: {
        ok: false,
        status: needsReview
          ? 'needs_human_review'
          : 'no_action_needed',
        errors: invalidClaims
          ? ['Unverified disruptions were supplied by Agent 2']
          : [],
        warnings: [],
        requires_human_review: needsReview,
        report: s(h.report),
        rejected_disruptions: rejected,
        suspicious_emails: suspicious,
        verified_legitimate_emails: legitimate,
        simulator_errors: arr(h.simulator_errors),
        ctx: null
      }
    });

    continue;
  }

  // CASE 2: Agent 2 claims a disruption but supplies no records.
  if (!disruptions.length) {
    results.push({
      json: {
        ok: false,
        status: 'needs_human_review',
        errors: ['Verified disruption list is empty'],
        warnings: [],
        requires_human_review: true,
        report: s(h.report),
        rejected_disruptions: rejected,
        ctx: null
      }
    });

    continue;
  }

  // CASE 3: Validate each verified disruption.
  for (const d of disruptions) {
    const errors = [];
    const warnings = [];

    const supplier_id = s(d.supplier_id).toUpperCase();

    const part_ids = [...new Set(
      arr(d.part_ids)
        .map(p => s(p).toUpperCase())
        .filter(Boolean)
    )];

    // A cancellation has no delay number: the PO never arrives.
    const dtype = s(d.disruption_type ?? d.type ?? d.event_type).toLowerCase();
    const cancelled =
      d.cancelled === true ||
      d.is_cancellation === true ||
      /cancel/.test(dtype);

    const delay_days = cancelled ? 0 : Number(d.delay_days);

    const affected_po_ids = [...new Set(
      arr(d.affected_po_ids)
        .map(p => s(p).toUpperCase())
        .filter(Boolean)
    )];

    const source_ids = [...new Set(
      arr(d.source_ids).map(s).filter(Boolean)
    )];

    if (d.verified !== true) {
      errors.push('Disruption is not verified by Agent 2');
    }

    if (!/^S\d{2}$/.test(supplier_id)) {
      errors.push('Invalid supplier ID');
    }

    if (!part_ids.length) {
      errors.push('No part IDs supplied');
    }

    for (const p of part_ids) {
      if (!/^P\d{3}$/.test(p)) {
        errors.push('Invalid part ID: ' + p);
      }
    }

    if (
      !cancelled && (
      !Number.isInteger(delay_days) ||
      delay_days <= 0 ||
      delay_days > 365)
    ) {
      errors.push('Invalid delay_days');
    }

    if (!source_ids.length) {
      errors.push('No source IDs supplied');
    }

    const valid = errors.length === 0;

    results.push({
      json: {
        ok: valid,
        status: valid
          ? 'ready_for_impact'
          : 'rejected_bad_input',
        errors,
        warnings,
        requires_human_review:
          h.requires_human_review === true || !valid,
        report: s(h.report),
        rejected_disruptions: rejected,
        ctx: valid ? {
          incident_id: s(d.incident_id) || 'unspecified',
          scenario_id: s(d.scenario_id ?? h.scenario_id) || null,
          supplier_id,
          part_ids,
          delay_days,
          cancelled,
          affected_po_ids,
          source_ids,
          include_in_transit: d.include_in_transit !== false,
          reasoning_from_agent2:
            s(d.assessment ?? d.reasoning_summary).slice(0, 500)
        } : null
      }
    });
  }
}

return results;

